#!/usr/bin/env python3
import csv, io, json, os, sys, unicodedata


def nid(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = s.casefold()
    out = []
    for ch in s:
        cat = unicodedata.category(ch)
        out.append(ch if (cat[0] == "L" or cat == "Nd") else " ")
    return " ".join("".join(out).split())


def read_batch(path):
    """Return (batch, revision, status, records) ; record = (ballot, contest, {rank: [marks]})
    mark = ('c', id) or ('w', text)"""
    with open(path, encoding="utf-8-sig", newline="") as f:
        text = f.read()
    records = []
    if path.endswith(".jsonl"):
        meta = None
        for line in text.split("\n"):
            if not line.strip():
                continue
            obj = json.loads(line)
            if meta is None:
                meta = obj
                continue
            rk = {}
            for m in obj.get("marks", []):
                r = int(m["rank"])
                if "write_in" in m and m["write_in"] is not None:
                    rk.setdefault(r, []).append(("w", m["write_in"]))
                elif m.get("candidate") is not None:
                    rk.setdefault(r, []).append(("c", m["candidate"]))
            records.append((obj.get("ballot"), obj["contest"], rk))
        if meta is None:
            return None
        return (str(meta["batch"]), int(str(meta["revision"]).strip()),
                str(meta["status"]).strip().lower(), records)
    lines = text.split("\n")
    meta = {}
    i = 0
    while i < len(lines):
        l = lines[i]
        if l.strip() == "":
            i += 1
            continue
        if l.startswith("#"):
            body = l[1:]
            if ":" in body:
                k, v = body.split(":", 1)
                meta[k.strip().lower()] = v.strip()
            i += 1
            continue
        break
    rows = [r for r in csv.reader(io.StringIO("\n".join(lines[i:]))) if r and any(c.strip() for c in r)]
    if not rows:
        return None
    header = [h.strip() for h in rows[0]]
    idx = {h: j for j, h in enumerate(header)}
    rankcols = []
    for h, j in idx.items():
        if h.startswith("rank") and h[4:].isdigit():
            rankcols.append((int(h[4:]), j))
    for r in rows[1:]:
        def cell(j):
            return r[j] if j < len(r) else ""
        rk = {}
        for n, j in rankcols:
            c = cell(j)
            if c.strip() == "":
                continue
            for part in c.split("|"):
                if part.strip() == "" and not part.startswith("WI:"):
                    continue
                if part.startswith("WI:"):
                    rk.setdefault(n, []).append(("w", part[3:]))
                elif part.strip().startswith("WI:"):
                    rk.setdefault(n, []).append(("w", part.strip()[3:]))
                else:
                    rk.setdefault(n, []).append(("c", part))
        records.append((cell(idx["ballot"]), cell(idx["contest"]), rk))
    return (meta["batch"], int(meta["revision"].strip()), meta["status"].strip().lower(), records)


def main(indir, outfile):
    with open(os.path.join(indir, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    cvr = os.path.join(indir, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        b = read_batch(p)
        if b is None:
            continue
        if b[0] not in best or b[1] > best[b[0]][1]:
            best[b[0]] = b
    by_contest = {}
    for b in best.values():
        if b[2] != "final":
            continue
        for ballot, contest, rk in b[3]:
            by_contest.setdefault(contest, []).append(rk)

    results = []
    for c in el["contests"]:
        results.append(count(c, by_contest.get(c["id"], [])))
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"election": el["election"], "contests": results}, f, ensure_ascii=False, indent=1)


def count(c, recs):
    maxr = c["max_ranks"]
    canon = {}      # normalized id -> id as written
    withdrawn = set()
    cands = []
    for cd in c.get("candidates", []):
        k = nid(cd["id"])
        canon[k] = cd["id"]
        if cd.get("status") == "withdrawn":
            withdrawn.add(k)
        else:
            cands.append(k)
    wtext = {}
    for w in c.get("write_ins", []):
        k = nid(w["id"])
        canon[k] = w["id"]
        cands.append(k)
        for t in [w["name"]] + list(w.get("aliases", [])):
            wtext.setdefault(norm_text(t), k)
    lot = [nid(x) for x in c.get("lot_order", [])]

    # parse ballots into ranking list: entries ('skip',) ('pass',) ('over',) ('choice', k)
    ballots = []
    for rk in recs:
        seen = set()
        rows = []
        for r in range(1, maxr + 1):
            marks = rk.get(r, [])
            s = set()
            for kind, v in marks:
                if kind == "w":
                    k = wtext.get(norm_text(v))
                    if k is not None:
                        s.add(k)
                else:
                    s.add(nid(v))
            if not s:
                rows.append(("skip",))
                continue
            s -= withdrawn
            if not s:
                rows.append(("pass",))
                continue
            left = s - seen
            seen |= s
            if not left:
                rows.append(("skip",))
            elif len(left) == 1:
                rows.append(("choice", next(iter(left))))
            else:
                rows.append(("over",))
        ballots.append(rows)

    def read(rows, cont):
        n = len(rows)
        for i, e in enumerate(rows):
            t = e[0]
            if t == "choice":
                if e[1] in cont:
                    return e[1]
            elif t == "over":
                return None
            elif t == "skip":
                if i + 1 >= n or rows[i + 1][0] == "skip":
                    return None
        return None

    total = len(ballots)
    cont = set(cands)
    hist = []
    rounds = []
    winner = None
    while True:
        tal = {k: 0 for k in cont}
        for rows in ballots:
            k = read(rows, cont)
            if k is not None:
                tal[k] += 1
        active = sum(tal.values())
        rnd = {"round": len(rounds) + 1,
               "tallies": {canon[k]: v for k, v in tal.items()},
               "exhausted": total - active, "eliminated": []}
        rounds.append(rnd)
        hist.append(tal)
        if active == 0:
            break
        top = max(tal, key=lambda k: tal[k])
        if tal[top] * 2 > active or len(cont) == 1:
            winner = canon[top]
            break
        zeros = [k for k in cont if tal[k] == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tal.values())
            tied = [k for k in cont if tal[k] == m]
            for h in reversed(hist[:-1]):
                if len(tied) == 1:
                    break
                mm = min(h[k] for k in tied)
                tied = [k for k in tied if h[k] == mm]
            if len(tied) > 1:
                tied = [max(tied, key=lambda k: lot.index(k) if k in lot else -1)]
            elim = tied
        rnd["eliminated"] = sorted(canon[k] for k in elim)
        cont -= set(elim)
    return {"contest": c["id"], "ballots": total, "winner": winner, "rounds": rounds}


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
